const svg=$('#hand-svg'), out=$('#hand-out');
const nSl=$('#hand-n'), nL=$('#hand-n-lbl'), add=$('#hand-add'), clr=$('#hand-clear');
const W=640,H=320, cx=W/2, cy=H/2-6, R=120;
let n=+nSl.value, edges=[]; // edges as "i-j" with i<j
function key(i,j){ return i<j? i+'-'+j : j+'-'+i; }
function positions(){
  const p=[];
  for(let i=0;i<n;i++){ const a=-Math.PI/2 + 2*Math.PI*i/n; p.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); }
  return p;
}
function maxEdges(){ return n*(n-1)/2; }
function addRandom(){
  if(edges.length>=maxEdges()) return;
  let tries=0;
  while(tries++<400){
    const i=Math.floor(Math.random()*n), j=Math.floor(Math.random()*n);
    if(i===j) continue;
    const k=key(i,j);
    if(!edges.includes(k)){ edges.push(k); return; }
  }
}
function render(){
  nL.textContent='n = '+n;
  const p=positions();
  svg.innerHTML='';
  const deg=new Array(n).fill(0);
  for(const e of edges){ const [i,j]=e.split('-').map(Number); deg[i]++; deg[j]++; }
  // edges
  for(const e of edges){ const [i,j]=e.split('-').map(Number);
    svg.appendChild(SVG('line',{x1:p[i][0],y1:p[i][1],x2:p[j][0],y2:p[j][1],stroke:'var(--cyan)','stroke-width':2,opacity:0.85})); }
  // vertices
  for(let i=0;i<n;i++){
    const odd=deg[i]%2===1;
    drawNode(svg,p[i][0],p[i][1], deg[i], {r:16, fill:'var(--panel2)', stroke: odd?'var(--pink)':'var(--green)'});
  }
  const sum=deg.reduce((a,b)=>a+b,0);
  const odds=deg.filter(d=>d%2===1).length;
  out.textContent =
    'edges |E| = '+edges.length+'   (max for n='+n+' is '+maxEdges()+')\n'+
    'degree sum  Σ deg(v) = '+sum+'      2|E| = '+(2*edges.length)+'   '+(sum===2*edges.length?'✓ equal':'✗')+'\n'+
    'odd-degree vertices (pink): '+odds+'   →  always even '+(odds%2===0?'✓':'✗');
}
nSl.addEventListener('input',()=>{ n=+nSl.value; edges=[]; render(); });
add.addEventListener('click',()=>{ addRandom(); render(); });
clr.addEventListener('click',()=>{ edges=[]; render(); });
// seed a couple of edges so the readout is non-trivial on load
addRandom(); addRandom(); render();

const svg=$('#tree-svg'), out=$('#tree-out');
const nSl=$('#tree-n'), nL=$('#tree-n-lbl'), sample=$('#tree-sample');
const W=640,H=320, cx=W/2, cy=H/2-6, R=120;
let n=+nSl.value, treeEdges=[];
// random Prüfer sequence -> labeled tree (uniform over all n^(n-2) trees)
function randomTree(){
  if(n<2){ treeEdges=[]; return; }
  if(n===2){ treeEdges=[[0,1]]; return; }
  const L=n-2, seq=[];
  for(let i=0;i<L;i++) seq.push(Math.floor(Math.random()*n));
  const degree=new Array(n).fill(1);
  for(const s of seq) degree[s]++;
  const edges=[];
  const seqCopy=[...seq];
  for(const s of seqCopy){
    // smallest leaf
    let leaf=-1; for(let v=0;v<n;v++){ if(degree[v]===1){ leaf=v; break; } }
    edges.push([leaf,s]); degree[leaf]--; degree[s]--;
  }
  // last edge: the two remaining degree-1 vertices
  const rem=[]; for(let v=0;v<n;v++) if(degree[v]===1) rem.push(v);
  edges.push([rem[0],rem[1]]);
  treeEdges=edges;
}
function positions(){
  const p=[];
  for(let i=0;i<n;i++){ const a=-Math.PI/2 + 2*Math.PI*i/n; p.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); }
  return p;
}
function fmt(x){ return x>=1e6 ? x.toExponential(3) : String(x); }
function render(){
  nL.textContent='n = '+n;
  const p=positions();
  svg.innerHTML='';
  // component count as the tree is grown edge-by-edge (here: full tree => 1 component)
  for(const [i,j] of treeEdges)
    svg.appendChild(SVG('line',{x1:p[i][0],y1:p[i][1],x2:p[j][0],y2:p[j][1],stroke:'var(--yellow)','stroke-width':2.2}));
  for(let i=0;i<n;i++) drawNode(svg,p[i][0],p[i][1], i+1, {r:16, fill:'var(--panel2)', stroke:'var(--blue)'});
  const cayley = n>=2 ? Math.pow(n,n-2) : 0;
  const comps = n - treeEdges.length; // each tree edge reduces component count by 1 (acyclic)
  out.textContent =
    'n = '+n+'   labeled trees: n^(n-2) = '+n+'^'+(n-2)+' = '+fmt(cayley)+'\n'+
    'sampled tree edges: '+treeEdges.length+'   (a tree on n vertices has n-1 = '+(n-1)+' edges)\n'+
    'components after adding all '+treeEdges.length+' edges: '+comps+'   (connected ⇔ 1 component)';
}
nSl.addEventListener('input',()=>{ n=+nSl.value; randomTree(); render(); });
sample.addEventListener('click',()=>{ randomTree(); render(); });
randomTree(); render();

function draw(g){
  while(G.firstChild)G.removeChild(G.firstChild);
  var byId={}; g.nodes.forEach(function(n){byId[n.id]=n;});
  var parent={}; g.nodes.forEach(function(n){parent[n.id]=n.id;});
  function find(a){ while(parent[a]!==a){ parent[a]=parent[parent[a]]; a=parent[a]; } return a; }
  var tree=[],cyc=[];
  g.edges.forEach(function(e){ var ra=find(e.u),rb=find(e.v); if(ra!==rb){ parent[ra]=rb; tree.push(e); } else cyc.push(e); });
  var roots={}; g.nodes.forEach(function(n){ roots[find(n.id)]=1; }); var c=0; for(var k in roots) c++;
  g.edges.forEach(function(e){ var a=byId[e.u],b=byId[e.v]; if(!a||!b)return;
    var isCyc=cyc.indexOf(e)>=0;
    G.appendChild(SVG('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:isCyc?'var(--pink)':'var(--green)','stroke-width':isCyc?2:3,'stroke-dasharray':isCyc?'5 4':'none'})); });
  g.nodes.forEach(function(nd){ G.appendChild(SVG('circle',{cx:nd.x,cy:nd.y,r:g.R,fill:'var(--cyan)',stroke:'var(--ink)','stroke-width':1.5})); });
  if(g.n===0){ out.innerHTML='empty graph \u2014 click empty space to add a vertex'; return; }
  var rank=tree.length, forest=cyc.length===0;
  out.innerHTML=g.n+' vertices \u00b7 '+c+' component'+(c===1?'':'s')+' \u00b7 spanning forest = <b style=\"color:var(--green)\">'+rank+'</b> edges (rank = n\u2212c) \u00b7 '+(forest?'<b style=\"color:var(--green)\">acyclic \u2014 a forest</b>':('<b style=\"color:var(--pink)\">'+(cyc.length===1?'1 edge closes':cyc.length+' edges close')+' a cycle</b>'));
}

const svg=$('#euler-svg'), out=$('#euler-out');
const nSl=$('#euler-n'), nL=$('#euler-n-lbl');
const presetC=$('#euler-cycle'), presetK=$('#euler-complete'), clr=$('#euler-clear');
const W=640,H=320, cx=W/2, cy=H/2-6, R=120;
let n=+nSl.value, adj=[];
function reset(){ adj=Array.from({length:n},()=>new Array(n).fill(0)); }
function toggle(i,j){ if(i===j) return; adj[i][j]=adj[j][i]=adj[i][j]?0:1; }
function cyclePreset(){ reset(); for(let i=0;i<n;i++){ const j=(i+1)%n; adj[i][j]=adj[j][i]=1; } }
function completePreset(){ reset(); for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){ adj[i][j]=adj[j][i]=1; } }
function positions(){ const p=[]; for(let i=0;i<n;i++){ const a=-Math.PI/2 + 2*Math.PI*i/n; p.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); } return p; }
function degrees(){ return adj.map(row=>row.reduce((a,b)=>a+b,0)); }
function edgeCount(){ let m=0; for(let i=0;i<n;i++) for(let j=i+1;j<n;j++) m+=adj[i][j]; return m; }
function connectedOnUsed(){ // connected ignoring isolated vertices
  const used=[]; for(let i=0;i<n;i++) if(degrees()[i]>0) used.push(i);
  if(used.length===0) return false;
  const seen=new Set([used[0]]), stack=[used[0]];
  while(stack.length){ const v=stack.pop(); for(let w=0;w<n;w++) if(adj[v][w] && !seen.has(w)){ seen.add(w); stack.push(w); } }
  return used.every(v=>seen.has(v));
}
function hamiltonian(){ // brute force over permutations fixing vertex 0
  if(edgeCount()<n) return false;
  const rest=[]; for(let i=1;i<n;i++) rest.push(i);
  let found=false;
  function perm(arr,k){
    if(found) return;
    if(k===arr.length){
      const cyc=[0,...arr];
      for(let i=0;i<cyc.length;i++){ const a=cyc[i], b=cyc[(i+1)%cyc.length]; if(!adj[a][b]) return; }
      found=true; return;
    }
    for(let i=k;i<arr.length;i++){ [arr[k],arr[i]]=[arr[i],arr[k]]; perm(arr,k+1); [arr[k],arr[i]]=[arr[i],arr[k]]; }
  }
  perm(rest,0); return found;
}
function render(){
  nL.textContent='n = '+n;
  const p=positions();
  svg.innerHTML='';
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++) if(adj[i][j])
    svg.appendChild(SVG('line',{x1:p[i][0],y1:p[i][1],x2:p[j][0],y2:p[j][1],stroke:'var(--cyan)','stroke-width':2,opacity:0.85}));
  // clickable midpoint pads for every possible edge
  for(let i=0;i<n;i++) for(let j=i+1;j<n;j++){
    const mx=(p[i][0]+p[j][0])/2, my=(p[i][1]+p[j][1])/2;
    const pad=SVG('circle',{cx:mx,cy:my,r:7,fill: adj[i][j]?'var(--yellow)':'transparent',
      stroke:'var(--line)','stroke-width':1, style:'cursor:pointer', 'data-i':i, 'data-j':j});
    svg.appendChild(pad);
  }
  const deg=degrees();
  for(let i=0;i<n;i++){ const odd=deg[i]%2===1; drawNode(svg,p[i][0],p[i][1], deg[i], {r:16, fill:'var(--panel2)', stroke: odd?'var(--pink)':'var(--green)'}); }
  const odds=deg.filter(d=>d%2===1).length;
  const conn=connectedOnUsed();
  let euler;
  if(!conn) euler='no (graph on its edges is disconnected)';
  else if(odds===0) euler='YES — Eulerian circuit (all degrees even)';
  else if(odds===2) euler='trail only (exactly 2 odd vertices), no circuit';
  else euler='no ('+odds+' odd-degree vertices)';
  const ham=hamiltonian();
  out.textContent =
    'click a small dot on an edge slot to toggle that edge.\n'+
    'degrees: ['+deg.join(', ')+']   odd-degree count: '+odds+'\n'+
    'Eulerian: '+euler+'\n'+
    'Hamiltonian cycle exists? '+(ham?'YES ✓':'no')+'   (brute-forced — NP-complete in general)';
}
svg.addEventListener('click',e=>{
  const t=e.target;
  if(t && t.hasAttribute && t.hasAttribute('data-i')){ toggle(+t.getAttribute('data-i'), +t.getAttribute('data-j')); render(); }
});
nSl.addEventListener('input',()=>{ n=+nSl.value; cyclePreset(); render(); });
presetC.addEventListener('click',()=>{ cyclePreset(); render(); });
presetK.addEventListener('click',()=>{ completePreset(); render(); });
clr.addEventListener('click',()=>{ reset(); render(); });
cyclePreset(); render();

const svg=$('#planar-svg'), out=$('#planar-out');
const nSl=$('#planar-n'), nL=$('#planar-n-lbl');
const add=$('#planar-add'), tri=$('#planar-tri'), clr=$('#planar-clear');
const W=640,H=320, cx=W/2, cy=H/2-6, R=118;
let V=+nSl.value, edges=[];
function key(i,j){ return i<j? i+'-'+j : j+'-'+i; }
function positions(){ const p=[]; for(let i=0;i<V;i++){ const a=-Math.PI/2 + 2*Math.PI*i/V; p.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); } return p; }
function spanningTree(){ edges=[]; for(let i=1;i<V;i++) edges.push(key(0,i)); } // star: V-1 edges
function addOne(){
  for(let i=0;i<V;i++) for(let j=i+1;j<V;j++){ const k=key(i,j); if(!edges.includes(k)){ edges.push(k); return true; } }
  return false;
}
function triangulate(){ // outer cycle + fan from v0 = 2V−3 edges (the max for vertices in convex position)
  edges=[];
  for(let i=0;i<V;i++) edges.push(key(i,(i+1)%V)); // outer cycle
  for(let i=2;i<V-1;i++) edges.push(key(0,i));     // fan from vertex 0 across the polygon
}
function render(){
  nL.textContent='V = '+V;
  const p=positions();
  svg.innerHTML='';
  for(const e of edges){ const [i,j]=e.split('-').map(Number);
    svg.appendChild(SVG('line',{x1:p[i][0],y1:p[i][1],x2:p[j][0],y2:p[j][1],stroke:'var(--cyan)','stroke-width':1.8,opacity:0.85})); }
  for(let i=0;i<V;i++) drawNode(svg,p[i][0],p[i][1], i+1, {r:14, fill:'var(--panel2)', stroke:'var(--violet)'});
  const E=edges.length;
  const bound=3*V-6;
  const planarOK = E<=bound;
  const F=E - V + 2;  // Euler: face count of a CONNECTED planar embedding
  out.textContent = planarOK
    ? ('V = '+V+'   E = '+E+'   (E ≤ 3V−6 = '+bound+', within the planar limit)\n'+
       'Euler then fixes the faces: F = E − V + 2 = '+F+'  (connected planar drawing)\n'+
       'fan-triangulating the circle reaches E = 2V−3 = '+(2*V-3)+' — the most for vertices in convex position; the 3V−6 bound (e.g. the octahedron) needs interior vertices')
    : ('V = '+V+'   E = '+E+'\n'+
       'E > 3V−6 = '+bound+'  ⇒  NOT planar (every drawing crosses; contains a K5 or K3,3 minor)\n'+
       'Euler\x27s V − E + F = 2 holds only for planar graphs — no consistent face count here');
}
nSl.addEventListener('input',()=>{ V=+nSl.value; spanningTree(); render(); });
add.addEventListener('click',()=>{ addOne(); render(); });
tri.addEventListener('click',()=>{ triangulate(); render(); });
clr.addEventListener('click',()=>{ spanningTree(); render(); });
spanningTree(); render();

const svg=$('#color-svg'), out=$('#color-out'), pick=$('#color-graph');
const shuffle=$('#color-order'), run=$('#color-run');
const W=640,H=320, cx=W/2, cy=H/2-6;
const palette=['var(--yellow)','var(--cyan)','var(--pink)','var(--green)','var(--violet)','var(--orange)'];
let graph=null, order=[], colors=[];
function ring(n,r,ox,oy){ const p=[]; for(let i=0;i<n;i++){ const a=-Math.PI/2+2*Math.PI*i/n; p.push([ (ox||cx)+r*Math.cos(a), (oy||cy)+r*Math.sin(a) ]); } return p; }
function build(kind){
  if(kind==='c5'){ const pos=ring(5,120); const adj=[[1,4],[0,2],[1,3],[2,4],[3,0]]; return mk(pos,adj); }
  if(kind==='k4'){ const pos=ring(4,110); const adj=[[1,2,3],[0,2,3],[0,1,3],[0,1,2]]; return mk(pos,adj); }
  if(kind==='wheel'){ // hub + C5 rim => W6 (6 vertices)
    const rim=ring(5,118); const pos=[[cx,cy],...rim];
    const adj=[[1,2,3,4,5],[0,2,5],[0,1,3],[0,2,4],[0,3,5],[0,4,1]]; return mk(pos,adj); }
  // petersen: outer 5-cycle (0..4) + inner pentagram (5..9), spokes i<->i+5
  const outer=ring(5,135), inner=ring(5,68);
  const pos=[...outer,...inner];
  const adj=Array.from({length:10},()=>[]);
  for(let i=0;i<5;i++){ link(adj,i,(i+1)%5); link(adj,i,i+5); link(adj,5+i,5+((i+2)%5)); }
  return {pos,adj};
}
function link(adj,a,b){ if(!adj[a].includes(b)) adj[a].push(b); if(!adj[b].includes(a)) adj[b].push(a); }
function mk(pos,adj){ return {pos,adj}; }
function newOrder(){ order=graph.pos.map((_,i)=>i); for(let i=order.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [order[i],order[j]]=[order[j],order[i]]; } }
function greedy(){
  const n=graph.pos.length; colors=new Array(n).fill(-1);
  for(const v of order){ const used=new Set(); for(const w of graph.adj[v]) if(colors[w]>=0) used.add(colors[w]);
    let c=0; while(used.has(c)) c++; colors[v]=c; }
}
function render(){
  svg.innerHTML='';
  const {pos,adj}=graph;
  const seen=new Set();
  for(let i=0;i<pos.length;i++) for(const j of adj[i]){ const k=i<j?i+'-'+j:j+'-'+i; if(seen.has(k)) continue; seen.add(k);
    svg.appendChild(SVG('line',{x1:pos[i][0],y1:pos[i][1],x2:pos[j][0],y2:pos[j][1],stroke:'var(--line)','stroke-width':1.6})); }
  let Delta=0; for(let i=0;i<adj.length;i++) Delta=Math.max(Delta,adj[i].length);
  for(let i=0;i<pos.length;i++){
    const col = colors[i]>=0 ? palette[colors[i]%palette.length] : 'var(--panel2)';
    drawNode(svg,pos[i][0],pos[i][1], colors[i]>=0?(colors[i]+1):'', {r:15, fill:col, stroke:'var(--ink)', textColor:'#0b0d10'});
  }
  const usedColors = new Set(colors.filter(c=>c>=0)).size;
  let brooks;
  const isComplete = adj.every(a=>a.length===adj.length-1);
  const isOddCycle = adj.every(a=>a.length===2) && (adj.length%2===1);
  if(isComplete) brooks='complete graph ⇒ χ = Δ+1 = '+adj.length;
  else if(isOddCycle) brooks='odd cycle ⇒ χ = 3 = Δ+1 (Brooks exception)';
  else brooks='neither complete nor odd cycle ⇒ Brooks: χ ≤ Δ = '+Delta;
  out.textContent =
    'order: ['+order.map(v=>v+1).join(', ')+']\n'+
    'max degree Δ = '+Delta+'   greedy ceiling Δ+1 = '+(Delta+1)+'\n'+
    'colors used by greedy: '+(usedColors||'(press “run greedy”)')+'\n'+
    brooks;
}
function reset(){ graph=build(pick.value); newOrder(); colors=graph.pos.map(()=>-1); render(); }
pick.addEventListener('change',reset);
shuffle.addEventListener('click',()=>{ newOrder(); colors=graph.pos.map(()=>-1); render(); });
run.addEventListener('click',()=>{ greedy(); render(); });
reset();

const svg=$('#match-svg'), out=$('#match-out');
const kSl=$('#match-k'), kL=$('#match-k-lbl'), rand=$('#match-rand'), clr=$('#match-clear');
const W=640,H=340;
let k=+kSl.value, adj=[]; // adj[i][j]=1 means x_i ~ y_j
function reset(){ adj=Array.from({length:k},()=>new Array(k).fill(0)); }
function randomize(){ reset(); for(let i=0;i<k;i++) for(let j=0;j<k;j++) if(Math.random()<0.45) adj[i][j]=1; }
function xPos(i){ const top=70, gap=(H-120)/(k-1||1); return [180, top + i*gap]; }
function yPos(j){ const top=70, gap=(H-120)/(k-1||1); return [460, top + j*gap]; }
// max bipartite matching (Kuhn / augmenting paths). matchY[j] = i matched to y_j (or -1)
function maxMatching(){
  const matchY=new Array(k).fill(-1);
  function aug(i,vis){
    for(let j=0;j<k;j++){ if(adj[i][j] && !vis[j]){ vis[j]=true;
      if(matchY[j]===-1 || aug(matchY[j],vis)){ matchY[j]=i; return true; } } }
    return false;
  }
  let size=0;
  for(let i=0;i<k;i++){ const vis=new Array(k).fill(false); if(aug(i,vis)) size++; }
  return {matchY,size};
}
function hallViolation(){ // find S ⊆ X with |N(S)| < |S| (brute over subsets)
  for(let mask=1;mask<(1<<k);mask++){
    const S=[]; for(let i=0;i<k;i++) if(mask&(1<<i)) S.push(i);
    const N=new Set();
    for(const i of S) for(let j=0;j<k;j++) if(adj[i][j]) N.add(j);
    if(N.size<S.length) return {S,N:[...N]};
  }
  return null;
}
function render(){
  kL.textContent='|X| = |Y| = '+k;
  svg.innerHTML='';
  const {matchY,size}=maxMatching();
  const inM=new Set(); for(let j=0;j<k;j++) if(matchY[j]>=0) inM.add(matchY[j]+'-'+j);
  // all edges
  for(let i=0;i<k;i++) for(let j=0;j<k;j++) if(adj[i][j]){
    const a=xPos(i), b=yPos(j), m=inM.has(i+'-'+j);
    svg.appendChild(SVG('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],
      stroke: m?'var(--green)':'var(--line)', 'stroke-width': m?3:1.4, opacity: m?1:0.7})); }
  // clickable toggle pads near the X side for each (i,j)
  for(let i=0;i<k;i++) for(let j=0;j<k;j++){
    const a=xPos(i), b=yPos(j); const px=a[0]+(b[0]-a[0])*0.28, py=a[1]+(b[1]-a[1])*0.28;
    svg.appendChild(SVG('circle',{cx:px,cy:py,r:6, fill: adj[i][j]?'var(--cyan)':'transparent',
      stroke:'var(--line)','stroke-width':1, style:'cursor:pointer','data-i':i,'data-j':j})); }
  for(let i=0;i<k;i++){ const a=xPos(i); drawNode(svg,a[0],a[1],'x'+(i+1),{r:16,fill:'var(--panel2)',stroke:'var(--violet)',fontSize:12}); }
  for(let j=0;j<k;j++){ const b=yPos(j); drawNode(svg,b[0],b[1],'y'+(j+1),{r:16,fill:'var(--panel2)',stroke:'var(--blue)',fontSize:12}); }
  const hv=hallViolation();
  const perfect = size===k;
  out.textContent =
    'click a small dot to toggle edge x_i — y_j.   matched edges are thick green.\n'+
    'maximum matching size = '+size+'   (perfect needs '+k+')   '+(perfect?'PERFECT ✓':'')+'\n'+
    'König: min vertex cover = max matching = '+size+'\n'+
    (hv ? "Hall FAILS: S = {"+hv.S.map(i=>'x'+(i+1)).join(',')+"} has |N(S)| = "+hv.N.length+" < "+hv.S.length+" = |S|"
        : "Hall's condition holds for every S ⊆ X  ✓"+(perfect?' (so X is fully matched)':''));
}
